#include <iostream>

struct Guard {
    const char* name;
    explicit Guard(const char* n) : name(n) { std::cout << "acquire " << name << '\n'; }
    ~Guard() { std::cout << "release " << name << '\n'; }   // 离开作用域必被调用
};

int main() {
    {
        Guard g("lock");
        std::cout << "work\n";
    }                     // 作用域结束：自动 release，无需手动调用
    std::cout << "done";
}
